  "run": "inventory-audit-1",
  "task": "Audit audit-target against its SPEC.md for correctness defects. Use parallel finder subagents with distinct angles, then have fresh verifier subagents independently confirm or refute each candidate. Log all worker actions with worker ids to audit-target/workflow-log.jsonl. Do not modify any file under audit-target other than the log.",
  "phases": [
    {
      "id": "find",
      "workers": [
        {
          "id": "find-remove",
          "role": "reviewer",
          "goal": "Audit inventory/stock.py's Ledger.remove() against SPEC.md's remove/raise requirement and any other SPEC-stated behavior for sku/qty handling. Done when every remove()-related SPEC line has been checked against the implementation and any violation is reported as a finding.",
          "inputs": ["audit-target/SPEC.md", "audit-target/inventory/stock.py", "audit-target/inventory/report.py", "audit-target/test_stock.py"],
          "owns": []
        },
        {
          "id": "find-lowstock",
          "role": "reviewer",
          "goal": "Audit inventory/stock.py's Ledger.low_stock() threshold comparison against SPEC.md's low_stock requirement. Done when the exact comparison operator and boundary behavior have been checked against the SPEC wording and any mismatch is reported as a finding.",
          "inputs": ["audit-target/SPEC.md", "audit-target/inventory/stock.py", "audit-target/inventory/report.py", "audit-target/test_stock.py"],
          "owns": []
        },
        {
          "id": "find-csv",
          "role": "reviewer",
          "goal": "Audit CSV parsing and unit conversion (price_dollars in CSV rows vs. cents stored in the ledger, per SPEC.md) across inventory/report.py's parse_csv_line and inventory/stock.py's add(). Done when every SPEC line about CSV rows/units has been checked against the implementation and any violation is reported as a finding.",
          "inputs": ["audit-target/SPEC.md", "audit-target/inventory/stock.py", "audit-target/inventory/report.py", "audit-target/test_stock.py"],
          "owns": []
        },
        {
          "id": "find-total",
          "role": "reviewer",
          "goal": "Audit total_value_cents() and add()'s aggregation of qty/price for a repeated sku against SPEC.md's total_value_cents formula. Done when the SPEC's total_value_cents definition has been checked against the implementation, including edge cases like re-adding an existing sku with a different price, and any violation is reported as a finding.",
          "inputs": ["audit-target/SPEC.md", "audit-target/inventory/stock.py", "audit-target/inventory/report.py", "audit-target/test_stock.py"],
          "owns": []
        },
        {
          "id": "find-report",
          "role": "reviewer",
          "goal": "Audit inventory/report.py's format_report() and parse_csv_line() for correctness against SPEC.md, including consistency with the ledger's stored cents values and CSV row format. Done when every SPEC line relevant to reporting/parsing has been checked against the implementation and any violation is reported as a finding.",
          "inputs": ["audit-target/SPEC.md", "audit-target/inventory/stock.py", "audit-target/inventory/report.py", "audit-target/test_stock.py"],
          "owns": []
        }
      ]
    },
    {
      "id": "verify",
      "workers": [
        {
          "id": "verify-1",
          "role": "verifier",
          "goal": "Independently confirm or refute each assigned candidate by reading the actual code and SPEC.md yourself; do not trust the finder's claim without checking.",
          "inputs": ["audit-target/SPEC.md", "audit-target/inventory/stock.py", "audit-target/inventory/report.py", "audit-target/test_stock.py"],
          "owns": [],
          "candidates": [
            {"id": "find:find-remove:r1:F1", "owner": "find-remove", "path": "audit-target/inventory/stock.py", "issue": "SPEC.md line 3 requires Ledger.remove(sku, qty) to raise ValueError if qty exceeds current stock; remove() never checks this and just subtracts, allowing qty to go negative silently."},
            {"id": "find:find-lowstock:r1:F1", "owner": "find-lowstock", "path": "audit-target/inventory/stock.py", "issue": "SPEC.md line 4 states low_stock(threshold) returns SKUs with qty <= threshold; low_stock() uses strict qty < threshold, excluding items exactly at the threshold."}
          ]
        },
        {
          "id": "verify-2",
          "role": "verifier",
          "goal": "Independently confirm or refute each assigned candidate by reading the actual code and SPEC.md yourself; do not trust the finder's claim without checking.",
          "inputs": ["audit-target/SPEC.md", "audit-target/inventory/stock.py", "audit-target/inventory/report.py", "audit-target/test_stock.py"],
          "owns": [],
          "candidates": [
            {"id": "find:find-remove:r1:F2", "owner": "find-remove", "path": "audit-target/inventory/stock.py", "issue": "SPEC.md line 4 states low_stock(threshold) returns SKUs with qty <= threshold; low_stock() uses strict qty < threshold, excluding items exactly at the threshold (same underlying bug as find:find-lowstock:r1:F1, reported independently by a second finder)."},
            {"id": "find:find-csv:r1:F1", "owner": "find-csv", "path": "audit-target/inventory/report.py", "issue": "SPEC.md line 5 states CSV rows are sku,qty,price_dollars and the ledger stores cents; parse_csv_line() does int(price) with no dollars-to-cents conversion, returning the raw dollar figure (and raising ValueError on any decimal price string like '19.99')."}
          ]
        },
        {
          "id": "verify-3",
          "role": "verifier",
          "goal": "Independently confirm or refute each assigned candidate by reading the actual code and SPEC.md yourself; do not trust the finder's claim without checking.",
          "inputs": ["audit-target/SPEC.md", "audit-target/inventory/stock.py", "audit-target/inventory/report.py", "audit-target/test_stock.py"],
          "owns": [],
          "candidates": [
            {"id": "find:find-total:r1:F1", "owner": "find-total", "path": "audit-target/inventory/stock.py", "issue": "SPEC.md line 6 defines total_value_cents as sum of qty * price_cents; add() only accumulates qty for an existing sku and silently discards a new price_cents argument, so re-adding an existing sku at a different price leaves the stale price in place and total_value_cents undercounts/overcounts the newly added units."},
            {"id": "find:find-report:r1:F1", "owner": "find-report", "path": "audit-target/inventory/report.py", "issue": "SPEC.md line 5 states CSV rows are sku,qty,price_dollars and the ledger stores cents; parse_csv_line() does int(price) with no dollars-to-cents conversion (same underlying bug as find:find-csv:r1:F1, reported independently by a second finder)."}
          ]
        }
      ]
    }
  ]
}

